import{_ as l,a0 as o,w as p,s as d,ao as h,I as e,x as i,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"既然float不能表示所有的int，那为什么在类型转换时C++将int转换成float？ | LCTT x X-CMD","titleTemplate":false,"description":"既然float不能表示所有的int，那为什么在类型转换时C++将int转换成float？ | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"既然float不能表示所有的int，那为什么在类型转换时C++将int转换成float？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"既然float不能表示所有的int，那为什么在类型转换时C++将int转换成float？ | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150124 Why does C++ promote an int to a float when a float cannot represent all int values","title":"既然float不能表示所有的int，那为什么在类型转换时C++将int转换成float？","tag":"201505","desc":""},"relativePath":"201505/20150124 Why does C++ promote an int to a float when a float cannot represent all int values.md","filePath":"[post].md"}'),r={name:"201505/20150124 Why does C++ promote an int to a float when a float cannot represent all int values.md"};function k(f,t,u,g,C,E){const s=o("Link");return p(),d("div",null,[t[13]||(t[13]=h(`<h1 id="既然float不能表示所有的int-那为什么在类型转换时c-将int转换成float" tabindex="-1">既然float不能表示所有的int，那为什么在类型转换时C++将int转换成float？ <a class="header-anchor" href="#既然float不能表示所有的int-那为什么在类型转换时c-将int转换成float" aria-label="Permalink to “既然float不能表示所有的int，那为什么在类型转换时C++将int转换成float？”">​</a></h1><p>###问题：</p><p>代码如下：</p><div class="language-C"><button title="Copy Code" class="copy"></button><span class="lang">C</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 23</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> f </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3.14</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> f)</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 执行某段代码</span></span></code></pre></div><p>编译器会将i转换成float类型，然后比较这两个float的大小，但是float能够表示所有的int吗？为什么没有将int和float转换成double类型进行比较呢？</p><p>###回答：</p><p>在整型数的演变中，当<code>int</code>变成<code>unsigned</code>时，会丢掉负数部分（有趣的是，这样的话，<code>0u &lt; -1</code>就是对的了）。</p><p>和C语言中的大部分机制（在C++中得到继承）一样，就硬件操作而言，常见的算术转换应该简明易懂。C语言的发明者精通他们所使用机器上的汇编语言，他们编写的C语言对他们和像他们一样编写程序的人有直接的意义，直到使用汇编语言编写（诸如UNIX内核）的程序时。</p><p>现如今，一般来说，处理器并不具有混合类型的指令系统（如float和double相加、比较int和float，诸如此类），因为如果这样做造成芯片晶圆的巨大浪费——如果你想支持更多不同的类型，你不得不实现更多的操作码。然而，在实际中，你只有实现&quot;add int to int&quot;、&quot;compare float to float&quot;和&quot;multiply unsigned with unsigned&quot;等功能的常见指令，这使得优先进行算术转换变得很有必要——它们是指令系统中两种类型的映射关系，它们中的大部分很有用处。</p><p>从习惯编写低级别机器代码的编程人员的角度来说，如果有了混合类型，那么在一般情况下最有可能使用的汇编指令就是那些只需要进行最少类型转换的指令。其中，有一种特殊情况就是浮点数的转换，特别是在20世纪70年代早期，当时C语言正在被开发，计算机运行速度很慢，而浮点数的计算是通过软件完成的，所以进行转换的成本很高。这拖慢了常用算术运算的转换开发——当时只有一种操作数实现了转换（这个例外就是long到unsigned int的转换，这种转换没有任何要求，在大部分机器上都可以进行。当然并不是全部，因为总有例外情况）。</p><p>所以，编写常用的算术转换是为了完成汇编程序员在大部分时间需要做的事情：即有两种不匹配的类型，将一种转换成另一种。这也就是汇编代码所做的事情，除非有特别原因需要进行其它类型转换。对于那些习惯编写汇编代码的人来说，除非是特殊需要，才会被迫去编写一种不同的类型转换。显然，这种情况下提出编写转换是很自然的事情。虽然，你可以简单地写成这样</p><div class="language-C"><button title="Copy Code" class="copy"></button><span class="lang">C</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) f)</span></span></code></pre></div><p>顺便提一下，在这个问题中有趣的是，<code>unsigned</code>的优先级高于<code>int</code>，所以把<code>int</code>和<code>unsigned</code>进行比较时，最终进行的是unsigned类型的比较（开头提到的<code>0u &lt; -1</code>就是这个道理）。我猜测这可能是在早些时候（计算机发展初期），当时的人们认为<code>unsigned</code>比<code>int</code>在所表示的数值范围上受到的限制更小：现在还不需要符号位，所以可以使用额外的位来表示更大的数值范围。如果你觉得<code>int</code>可能会溢出，那么就使用unsigned好了——在使用16位表示的ints时这个担心会更明显。</p><hr>`,14)),e("p",null,[t[1]||(t[1]=i("via: ",-1)),a(s,{href:"http://stackoverflow.com/questions/28010565/why-does-c-promote-an-int-to-a-float-when-a-float-cannot-represent-all-int-val/28011249#28011249"},{default:n(()=>[...t[0]||(t[0]=[i("stackoverflow",-1)])]),_:1})]),e("p",null,[t[5]||(t[5]=i("作者：",-1)),a(s,{href:"http://stackoverflow.com/users/4301306/wintermute"},{default:n(()=>[...t[2]||(t[2]=[i("wintermute",-1)])]),_:1}),t[6]||(t[6]=i(" 译者：",-1)),a(s,{href:"https://github.com/KayGuoWhu"},{default:n(()=>[...t[3]||(t[3]=[i("KayGuoWhu",-1)])]),_:1}),t[7]||(t[7]=i(" 校对：",-1)),a(s,{href:"https://github.com/wxy"},{default:n(()=>[...t[4]||(t[4]=[i("wxy",-1)])]),_:1})]),e("p",null,[t[10]||(t[10]=i("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[i("LCTT",-1)])]),_:1}),t[11]||(t[11]=i(" 原创翻译，",-1)),a(s,{href:"http://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[i("Linux中国",-1)])]),_:1}),t[12]||(t[12]=i(" 荣誉推出",-1))])])}const b=l(r,[["render",k]]);export{c as __pageData,b as default};
